import {renderLaunchStructure} from './launch-structure.js';
import {renderInterface} from './interface-view.js';
import {pointingApproach} from './flight-attitude-view.js';
import {deploymentReferences} from './deployment-view.js';
import {icon} from './icons.js';
import {propulsionSectionDrawing} from './propulsion-drawing.js';
import {propulsionReview} from './spacecraft-architecture.js';
import {renderArchitectureTrade} from './architecture-trades.js';
import {referenceAssociation,referenceMetadata} from './reference-configurations.js';
import {architectureFamily} from './architecture-families.js';
import {commissioningClock} from './commissioning-clock.js';

export const vehicleBaseline='ODC-01 / Rev I';
const number=(v,d=2)=>Number.isFinite(v)?v.toLocaleString('en-US',{minimumFractionDigits:0,maximumFractionDigits:d}):'—';
const esc=v=>String(v).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
const rule=(id,scope,fixed,variable)=>({id,scope,fixed,variable});
export const groundRules=Object.freeze([
 rule('SC-01','Structure','A rectangular launch-axis spine links reinforced mounting stations on the four long faces to corner longerons, the aft bulkhead and the adapter. The internal racks and aft tank frame share this structure.','Bus dimensions, wall mass, shielding and equipment accommodation.'),
 rule('SC-02','Power','Four flexible solar blankets extend to port and starboard (±X). Each tip drum travels on two strain-energy booms from a spacecraft-mounted rotary head. The tensioned wings track about X. Batteries sit inside the enclosure.','Cell technology, wing area, battery chemistry and installed energy.'),
 rule('SC-03','Thermal','Two separately isolatable, double-sided radiator banks fold against the ±Y walls. Root bearings and release fittings attach at separate axial frame stations. Each has a damped root hinge, the installed even count of folding panels, and flexible supply and return crossings. Panel pairs form parallel hydraulic sections with manifold mass and losses included. After the fold hinges lock, the root cants each bank outward to clear its neighbor. A separately driven rotary fluid interface twists the bank about its long axis. The emitting faces can turn edge-on to sunlight while the photovoltaic wings track the Sun. The twist joint has ±105° mechanical stops. Its command range narrows when bank spacing or the communications terminals need more clearance. Its installation and swept clearances are design-study assumptions. Cold plates and pumped supply and return lines connect the payload to the banks.','Radiator area, coating, heat load, transport resistance and pump draw.'),
 rule('SC-04','Compute and data','A transverse rack lattice repeats along the launch axis, inside the primary box. Slot dimensions and installation clearances determine how many computer trays fit. Occupied slots locate the compute mass.','Accelerator and host population, storage capacity, network throughput and power.'),
 rule('SC-05','Propulsion','Two internal liquid tanks, one helium bottle and two pressure-fed engines. Both engines fire through the −Z launch-adapter deck. Net nominal thrust points toward +Z.','Tank volumes, load, mixture ratio, selected engine performance and burn duration.'),
 rule('SC-06','Pointing and communications','Four CMGs, three magnetic torquer axes, two S-band patches, one steerable Ka-band reflector and one optical terminal.','Momentum capacity, magnetic dipole, dish and aperture size, link choice and pointing demand.'),
 rule('SC-07','Deployment and burns','Wing rollout and tensioning precede the two radiator deployments. Each bank unfolds and latches before its coolant branch opens. Chemical burns require the completed deployment sequence.','Deployment clearances, thrust alignment and burn feasibility for the sized vehicle.'),
 rule('SC-08','Launch interface','ODC-LI-01 fixes the aft mounting face and bolt clocking on the spacecraft. The passive upper fitting remains on the spacecraft on release.','The adapter’s launcher face, axial stand-off and launch-only mass follow the installation.')
].map(Object.freeze));
export function groundRulesFor(h){
 const family=architectureFamily(h);
 if(family.id==='protected-core'&&family.communicationsPackageId==='full')return groundRules;
 const thermal=h.energySystem?.thermal,platform=family.payloadLocation==='radiator',fixedRadiator=family.radiatorTracking==='fixed-after-deployment';
 const attachment=h.payloadInterface,rectangular=attachment?.attachmentShape==='rectangular-lugs';
 return [
  rule('SC-01','Structure',`${family.label}. The resolved geometry defines the bus, appendage roots and spacecraft attachment. Equipment accommodation and load paths are preliminary allocations; the public concept does not qualify the modeled structure.`,'Bus dimensions, wall mass, local shielding and equipment accommodation.'),
  rule('SC-02','Power',`${family.solarWingCount} solar blankets feed the selected electrical architecture. Their installed areas, root stations and deployed dimensions come from this family’s physical manifest. Batteries remain inside the service bay.`,'Cell technology, installed blanket area, battery chemistry and installed energy.'),
  rule('SC-03','Thermal',`${thermal?.topology||family.thermalTopology}. ${fixedRadiator?'The radiator geometry is fixed after deployment; no independent radiator Sun-avoidance drive is credited.':'Each allocated radiator bank unfolds, latches and uses the modeled root/trim mechanism within its clearance limits.'} ${thermal?.redundancy||'Redundancy and qualified transport capacity remain to be established.'}`,'Radiator area, coating, transport capacity, temperatures and electrical demand.'),
  rule('SC-04','Compute and data',platform?'Compute and local shielding ride on the moving radiator platform. The service bus contains the remaining support equipment. The spreader, tray accommodation and harness crossing are represented separately.':'Compute trays occupy the selected family’s allocated payload bay. Tray slots, installation clearances and current equipment mass determine the accommodation and mass properties.','Accelerator and host population, storage capacity, network throughput and power.'),
  rule('SC-05','Propulsion','The study allocates two internal liquid tanks, one helium bottle and two pressure-fed engines. The engines exhaust through the −Z attachment region and nominal thrust points toward +Z. This common project installation is not attributed to the reference provider.','Tank volumes, load, mixture ratio, selected engine performance and burn duration.'),
  rule('SC-06','Pointing and communications',`The study carries four CMGs, three magnetic torquer axes, ${family.sPatchCount} S-band patches, ${family.kaTerminalCount} steerable Ka-band reflector and ${family.opticalTerminalCount} optical terminal${family.opticalTerminalCount===1?'':'s'}. Physical mounting stations follow the selected family. Provider hardware identity and performance remain separate evidence fields.`,'Momentum capacity, magnetic dipole, dish and aperture size, link choice and pointing demand.'),
  rule('SC-07','Deployment and burns',`${family.solarWingCount} blankets and ${family.radiatorBankCount} radiator ${family.radiatorBankCount===1?'platform follow':'banks follow'} the family’s release and latch sequence. ${platform?'The compute platform deploys before the arrays; its hinge carries power and data without a pumped-fluid crossing.':'The physical model retains the declared fold/roll sequence and thermal connection gates.'} The ${number(commissioningClock(h).durationS/60,0)} min commanded sequence is an allocation. Chemical burns require completed commissioning.`,'Mechanism timing, swept clearances, thrust alignment and burn feasibility.'),
  rule('SC-08','Launch interface',rectangular?`${attachment.id} uses four allocated corner attachments and an open engine cradle. No provider fastener drilling, restraint or dispenser qualification is implied.`:`${attachment?.id||'Selected circular interface'} retains the allocated circular aft attachment. Provider acceptance and load qualification remain open.`,'The launcher-side adapter, axial stand-off and launch-only mass follow the selected installation.')
 ];
}
const precedents=[
 ['Boeing 702','Internal tank cavity and separate thrust face','The DIRECTV spacecraft filing describes four propellant tanks and two helium tanks in the bus cavity. Its main thruster and several smaller thrusters occupy the aft face. ODC adopts that separation with a two-liquid-tank bay.','FCC filing · spacecraft bus §13','https://fcc.report/IBFS/SAT-LOA-20040909-00168/421284.pdf'],
 ['Lockheed Martin A2100 / GOES-R','A complete pressure-fed circuit','NOAA’s schematic traces helium storage, regulation and isolation, separate liquid inventories, filters and engine valves. ODC uses this feed arrangement for two main engines. GOES-R itself used multiple thruster families.','NOAA · GOES-R Series Data Book, fig. 13-1','https://www.ospo.noaa.gov/resources/documents/GOES-RSeriesDataBook.pdf'],
 ['ESA Artemis','Propulsion and thermal faces','Artemis placed tanks, the apogee engine and most of its plumbing in a central propulsion module. Its north and south panels provided the principal thermal radiation surfaces. ODC assigns its deployable radiators the opposite end from the exhaust.','ESA Bulletin 91 · Satellite Platform','https://www.esa.int/esapub/bulletin/bullet91/b91dick.htm']
];
const action=(attr,label,ic)=>`<button class="btn" ${attr}>${icon(ic,14)}${label}</button>`;
const vector=p=>p.map(x=>number(x,3)).join(' / ');

export function architectureReadings(h,remaining=h.propellantKg,pose=null){
 const p=propulsionReview(h,remaining,pose);
 return [
  ['Tank installation margin',p.tankMarginM,'m'],
  ['Radiator to plume margin',p.radiatorMarginM,'m'],
  ['Solar wing to plume margin',p.wingMarginM,'m'],
  ['Assumed plume half-angle',p.plumeHalfAngleDeg,'deg'],
  ['Thrust-line miss distance',p.missM,'m'],
  ['Residual burn torque',p.torqueNm,'N·m'],
  ['Angle from thrust axis to CM',p.alignmentDeg,'deg'],
  ['Alignment screen limit',p.alignmentLimitDeg,'deg']
 ].map(([quantity,value,unit])=>({quantity,value,unit}));
}

export function renderArchitecture(h,s){
 const remaining=s?.propellantKg??h.propellantKg;
 const p=propulsionReview(h,remaining,s);
 const conditions=[['Loaded on orbit',h.propellantKg],['Selected instant',remaining],['Trapped residual',h.propellantKg*h.input.residualFraction]];
 const association=referenceAssociation(h),metadata=association?referenceMetadata(association.id,association.revision):null,family=architectureFamily(h),thermal=h.energySystem?.thermal;
 const measurements=architectureReadings(h,remaining,s);
 const pressure=h.propulsion;
 const fluidNames=h.input.engine==='aero'?['Aerozine-50','NTO','Helium']:['MMH','MON-3','Helium'];
 const tanks=pressure.tanks.map((t,i)=>[fluidNames[i],number(t.volumeL,2)+' L',number(2*t.radiusM,3)+' m',i<2?number(100*h.input.tankFill,1)+'% liquid':'Compressed gas',i<2?number(pressure.feedPa/1e6)+' MPa':number(pressure.bottlePa/1e6)+' MPa']);
 const fixed=groundRulesFor(h).map(r=>`<tr><td><small>${r.id}</small><strong>${r.scope}</strong></td><td>${r.fixed}</td><td>${r.variable}</td></tr>`).join('');
 const row=(cells)=>'<tr>'+cells.map(v=>'<td>'+v+'</td>').join('')+'</tr>';
 return `<div class="arch-sheet">
 <section class="arch-lead panel"><div><span class="arch-index">VEHICLE DEFINITION &nbsp; / &nbsp; REV I</span><h2>${association?esc(association.name):esc(family.label)}</h2>${metadata?`<p>${esc(metadata.adaptation)} ${association.modified?'This is a modified study variant.':''}</p>`:''}<p>${esc(family.label)} carries ${family.solarWingCount} solar blankets and ${family.radiatorBankCount} radiator ${family.radiatorBankCount===1?'platform':'banks'}. ${family.payloadLocation==='radiator'?'The compute payload moves with the radiator platform.':'The compute payload occupies the allocated equipment bay.'} ${esc(thermal?.topology||family.thermalTopology)}. Mission changes evaluate this installed spacecraft. Resource, geometry and qualification status are reported separately below.</p></div><div class="arch-actions"><button class="btn" data-chapter="commissioning">Watch deployment →</button><button class="btn" data-attitude-flight>Inspect flight pointing →</button>${action('data-inspect-bay="true"','Inspect propulsion in 3D','box')}${action('data-page="equipment"','Master equipment list','list-checks')}</div></section>
 ${renderArchitectureTrade(h)}
 ${renderLaunchStructure(h,'architecture')}
 <section class="panel arch-figure"><div class="panelhead"><h2>${icon('fuel',16)} Spacecraft packaging</h2><span class="arch-stamp">CURRENT BUILD</span></div>${propulsionSectionDrawing(h,s)}<div class="arch-strip"><span>Bus, X × Y × Z <b>${number(h.bodyWidthM)} × ${number(h.bodyHeightM)} × ${number(h.bodyLengthM)} m</b></span><span>Launch propellant <b>${number(h.propellantKg)} kg</b></span><span>Combined thrust <b>${number(h.input.thrustN)} N</b></span></div></section>
 ${renderInterface(h,true)}
 <section class="panel"><div class="panelhead"><h2>Accommodation and launch balance</h2></div><div class="arch-pad"><p>${family.payloadLocation==='radiator'?'Compute trays and their shielding belong to the moving radiator platform. Propulsion, batteries, avionics and the four gyros remain service-bus allocations.':'The liquid vessels and compute trays occupy distinct allocated equipment stations. Batteries, avionics and four gyros complete the service installation.'} The two engine bells sit inside an open stand-off above the separation interface. These allocations establish the current mass properties, not a provider-qualified accommodation.</p><div class="arch-metrics"><div><small>Current outer bus volume</small><strong>${number(h.bodyWidthM*h.bodyHeightM*h.bodyLengthM,2)} m³</strong></div><div><small>Spacecraft CM above adapter base, stowed</small><strong>${number(h.fairing.stack.find(x=>x.part==='Insulated bus').z0M+h.bodyLengthM/2+p.stowedCM[2],2)} m</strong></div><div><small>Loaded liquids</small><strong>${number(h.propellantKg,1)} kg</strong></div><div><small>Compute trays incl. cold plates</small><strong>${number(h.massLedger.filter(r=>['compute','host'].includes(r.id)).reduce((a,r)=>a+r.kg,0),1)} kg</strong></div></div><p class="arch-method">The exterior bus volume includes the tank deck, frame, equipment clearances and avionics${family.payloadLocation==='radiator'?'; compute accommodation is on the platform':''}. Installed trays and empty positions are counted separately. Electrical supply, cooling, total launch mass and fairing fit also constrain an expansion.</p></div></section>
 <section class="panel"><div class="panelhead"><h2>${icon('list-checks',16)} Ground rules and assumptions</h2><span class="arch-stamp">SELECTED FAMILY</span></div><div class="arch-scroll" tabindex="0" aria-label="Ground rules table"><table class="arch-table"><thead><tr><th>Subsystem</th><th>Installed spacecraft architecture</th><th>What a study can size or select</th></tr></thead><tbody>${fixed}</tbody></table></div></section>
 <section class="panel"><div class="panelhead"><h2>${icon('fuel',16)} Pressure and propellant feed</h2><span class="arch-stamp">PRESSURE-FED BIPROPELLANT</span></div><div class="arch-pad"><p>Helium passes through the regulator and independent check valves into the gas space in each liquid tank. Separate fuel and oxidizer circuits feed the two injectors through isolation valves, filters and manifolds. Propellant management devices keep the liquid outlets supplied in microgravity.</p></div>
 <div class="arch-scroll" tabindex="0" aria-label="Internal vessel sizing"><table class="arch-table"><thead><tr><th>Vessel</th><th>Internal volume</th><th>Installed diameter</th><th>At launch</th><th>Initial pressure, absolute</th></tr></thead><tbody>${tanks.map(row).join('')}</tbody></table></div><div class="arch-pad"><p class="arch-method">Vessels use a spherical envelope. The regulator holds the ullages at ${number(pressure.feedPa/1e6)} MPa. At the selected instant, modeled bottle pressure is ${number(p.bottlePressureMPa)} MPa. The sizing calculation assumes ideal helium at ${number(pressure.temperatureK)} K.</p><a href="https://www.space-propulsion.com/spacecraft-propulsion/apogee-motors/" target="_blank" rel="noopener">ArianeGroup S400 apogee motor family ↗</a></div></section>
 <section class="panel"><div class="panelhead"><h2>${icon('crosshair',16)} Thrust alignment and clearance</h2><span class="arch-stamp">PRELIMINARY SCREEN</span></div><div class="arch-pad"><p>Each engine delivers half the selected thrust. The two thrust vectors add through the midpoint of the nozzle pair. The check uses the sized vehicle and its mass distribution to calculate the offset from the fixed thrust line and its resulting torque.</p>
 <div class="arch-verdict ${p.clear?'':'inspect'}"><strong>${p.clear?'Geometry and alignment screens pass':'Geometry or alignment requires review'}</strong><span>${p.engineRangeOK?'MMH engine pair within the reference thrust and mixture range.':'Engine sizing is outside the MMH reference thrust or mixture range, or uses a different chemistry.'}</span></div>
 <div class="arch-metrics">${measurements.map(m=>`<div><small>${m.quantity}</small><strong>${number(m.value,4)} <em>${m.unit}</em></strong></div>`).join('')}</div>
 <div class="arch-scroll" tabindex="0" aria-label="Mass properties at three propellant loads"><table class="arch-table"><thead><tr><th>Deployed mass case</th><th>Propellant</th><th>Center of mass X / Y / Z</th><th>Off-axis angle</th><th>Residual torque</th></tr></thead><tbody>${conditions.map(([l,m])=>{const a=propulsionReview(h,m,l==='Selected instant'?s:null);return row([l,number(m)+' kg',vector(a.cm)+' m',number(a.alignmentDeg,3)+'°',number(a.torqueNm,3)+' N·m'])}).join('')}</tbody></table></div>
 <p class="arch-method">Body coordinates are measured from the bus center. +Z points away from the adapter during launch. In the nominal nadir law, +Y points toward Earth and +Z follows the orbital track. The packed launch center of mass is ${vector(p.stowedCM)} m. The clearance screen uses a ${p.plumeHalfAngleDeg}° cone plus a ${p.alignmentLimitDeg}° angular allowance. Positive clearance indicates separation. The burn sequencer checks pointing and clearance before authorizing ignition. The spacecraft turns its +Z thrust axis toward the maneuver direction. The torque screen compares the offset load with ${number(h.input.cmgTorqueNm)} N·m of installed CMG torque. Plume spread, backflow, surface heating and contamination require engine-specific analysis. Mass properties use preliminary equipment allocations.</p><a href="https://standards.nasa.gov/system/files/tmp/JSC-67723_Propulsion_Standard_Basic_Final%20%281%29_0.pdf" target="_blank" rel="noopener">NASA JSC-67723 · plume effects, §3.1.8 ↗</a></div></section>
 ${pointingApproach(h)}${deploymentReferences(h)}<section class="panel"><div class="panelhead"><h2>${icon('book-open',16)} Flight design references</h2></div><div class="arch-sources">${precedents.map(([bus,topic,desc,label,url])=>`<article><small>${bus}</small><h3>${topic}</h3><p>${desc}</p><a href="${esc(url)}" target="_blank" rel="noopener">${label} ↗</a></article>`).join('')}</div></section></div>`;
}
